// Package nft is a multi-tenant GRC-721 NFT factory realm.
//
// Gno.land realms can't be deployed at runtime the way Solidity contracts
// can (every new realm is its own `addpkg` transaction with real source
// code). To still let *anyone* mint their own NFT collection without
// writing Gno code, this single realm hosts many independent GRC-721
// token instances ("collections") in an internal registry: users call
// CreateCollection to register one, then Mint into it.
package nft

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/tokens/grc721"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// MaxRoyaltyPercent caps creator royalties at 50% of a secondary sale.
const MaxRoyaltyPercent = 50

// nftToken is the subset of *grc721.royaltyNFT's method set this realm
// depends on. grc721.NewNFTWithRoyalty returns a pointer to an unexported
// concrete type, so it can't be named as a struct field type directly;
// Go/Gno interface satisfaction is structural, so this local interface
// lets us store it in Collection.token and keep the file readable.
type nftToken interface {
	Name() string
	Symbol() string
	TokenCount() int64
	BalanceOf(addr address) (int64, error)
	OwnerOf(tid grc721.TokenID) (address, error)
	TokenURI(tid grc721.TokenID) (string, error)
	SetTokenURI(caller address, tid grc721.TokenID, tURI grc721.TokenURI) (bool, error)
	IsApprovedForAll(owner, operator address) bool
	Approve(caller, to address, tid grc721.TokenID) error
	GetApproved(tid grc721.TokenID) (address, error)
	SetApprovalForAll(caller, operator address, approved bool) error
	TransferFrom(caller, from, to address, tid grc721.TokenID) error
	Mint(to address, tid grc721.TokenID) error
	Burn(tid grc721.TokenID) error
	RoyaltyInfo(tid grc721.TokenID, salePrice int64) (address, int64, error)
	SetTokenRoyalty(caller address, tid grc721.TokenID, info grc721.RoyaltyInfo) error
}

// Collection is one user-created NFT collection living inside this realm.
type Collection struct {
	id          string
	name        string
	symbol      string
	description string
	baseURI     string
	creator     address
	maxSupply   int64
	publicMint  bool // if true, anyone can Mint; otherwise only the creator
	royaltyPct  int64
	token       nftToken
	nextTokenID int64
	createdAt   int64
}

// CollectionInfo is the read-only, exported view of a Collection returned
// by view functions (safe to marshal / qeval from outside the realm).
type CollectionInfo struct {
	ID          string
	Name        string
	Symbol      string
	Description string
	BaseURI     string
	Creator     address
	MaxSupply   int64
	Minted      int64
	PublicMint  bool
	RoyaltyPct  int64
	CreatedAt   int64
}

var (
	collections          = avl.NewTree() // id -> *Collection
	collectionsByCreator = avl.NewTree() // "creator:id" -> id
	ownerIndex           = avl.NewTree() // "owner:collectionId:tokenId" -> true
	collCount            int64
)

// CreateCollection registers a brand-new GRC-721 collection owned by the
// caller and returns its collection ID. Set publicMint to true to let
// anyone mint into the collection; otherwise only the creator can.
func CreateCollection(cur realm, name, symbol, description, baseURI string, maxSupply, royaltyPct int64, publicMint bool) string {
	// Origin-caller (the tx's real signer) is used instead of
	// cur.Previous().Address() here: CreateCollection/Mint/Approve are
	// always meant to be invoked directly by a user, and per the gno.land
	// interrealm-phase-3 guidance, "PreviousRealm-based auth ... was not
	// a reliable immediate-caller check and should not be used as an
	// authorization boundary" for this kind of direct-EOA-action. Only
	// TransferFrom below actually needs the direct-caller distinction
	// (to let the marketplace act as an approved operator).
	caller := unsafe.OriginCaller()

	if maxSupply <= 0 {
		panic("maxSupply must be positive")
	}
	if royaltyPct < 0 || royaltyPct > MaxRoyaltyPercent {
		panic("royaltyPct must be between 0 and " + strconv.Itoa(MaxRoyaltyPercent))
	}

	collCount++
	id := strconv.FormatInt(collCount, 10)

	token := grc721.NewNFTWithRoyalty(0, cur, name, symbol)

	c := &Collection{
		id:          id,
		name:        name,
		symbol:      symbol,
		description: description,
		baseURI:     baseURI,
		creator:     caller,
		maxSupply:   maxSupply,
		publicMint:  publicMint,
		royaltyPct:  royaltyPct,
		token:       token,
		nextTokenID: 1,
		createdAt:   runtime.ChainHeight(),
	}
	collections.Set(id, c)
	collectionsByCreator.Set(caller.String()+":"+id, id)

	chain.Emit(
		"CollectionCreated",
		"id", id,
		"creator", caller.String(),
		"name", name,
		"symbol", symbol,
	)

	return id
}

// Mint mints the next token in a collection to the caller and returns the
// new token ID. Blocked once the collection reaches its declared max
// supply, and restricted to the collection creator unless publicMint was
// enabled at creation time.
func Mint(cur realm, collectionID, tokenURI string) string {
	caller := unsafe.OriginCaller()
	c := mustGetCollection(collectionID)

	if !c.publicMint && caller != c.creator {
		panic("minting into this collection is restricted to its creator")
	}
	if c.token.TokenCount() >= c.maxSupply {
		panic("collection has reached its max supply")
	}

	tidStr := strconv.FormatInt(c.nextTokenID, 10)
	c.nextTokenID++
	tid := grc721.TokenID(tidStr)

	if err := c.token.Mint(caller, tid); err != nil {
		panic(err)
	}
	if tokenURI != "" {
		if _, err := c.token.SetTokenURI(caller, tid, grc721.TokenURI(tokenURI)); err != nil {
			panic(err)
		}
	}
	if c.royaltyPct > 0 {
		// Newly minted tokens are owned by caller, so caller satisfies
		// SetTokenRoyalty's "caller must be current owner" check.
		if err := c.token.SetTokenRoyalty(caller, tid, grc721.RoyaltyInfo{
			PaymentAddress: c.creator,
			Percentage:     c.royaltyPct,
		}); err != nil {
			panic(err)
		}
	}

	ownerIndex.Set(caller.String()+":"+collectionID+":"+tidStr, true)

	chain.Emit(
		"NFTMinted",
		"collection", collectionID,
		"tokenId", tidStr,
		"to", caller.String(),
	)

	return tidStr
}

// Transfer / approval wrappers.
//
// Approve/SetApprovalForAll/Burn are direct EOA actions, so they use
// unsafe.OriginCaller() like Mint/CreateCollection above. TransferFrom is
// the exception: it derives caller from cur.Previous().Address() — the
// direct/immediate caller of this specific frame — because
// gno.land/r/hazen/nftmarket calls it via cross(cur) once a seller has
// approved the marketplace's realm address. From the token's perspective,
// the "caller" of that transfer must be the marketplace realm itself
// (the approved operator), not OriginCaller() (which would still be the
// buyer and was never approved to move the seller's token).

// Approve approves `to` to transfer a single token on the caller's behalf.
func Approve(cur realm, collectionID, tokenID string, to address) {
	caller := unsafe.OriginCaller()
	c := mustGetCollection(collectionID)
	if err := c.token.Approve(caller, to, grc721.TokenID(tokenID)); err != nil {
		panic(err)
	}
}

// SetApprovalForAll grants/revokes operator permission across all of the
// caller's tokens in one collection (e.g. approving the marketplace realm
// once instead of per-token).
func SetApprovalForAll(cur realm, collectionID string, operator address, approved bool) {
	caller := unsafe.OriginCaller()
	c := mustGetCollection(collectionID)
	if err := c.token.SetApprovalForAll(caller, operator, approved); err != nil {
		panic(err)
	}
}

// TransferFrom transfers a token from `from` to `to`. caller must be the
// owner or an approved operator/spender.
func TransferFrom(cur realm, collectionID, tokenID string, from, to address) {
	caller := cur.Previous().Address()
	c := mustGetCollection(collectionID)
	tid := grc721.TokenID(tokenID)

	if err := c.token.TransferFrom(caller, from, to, tid); err != nil {
		panic(err)
	}

	ownerIndex.Remove(from.String() + ":" + collectionID + ":" + tokenID)
	ownerIndex.Set(to.String()+":"+collectionID+":"+tokenID, true)

	chain.Emit(
		"Transfer",
		"collection", collectionID,
		"tokenId", tokenID,
		"from", from.String(),
		"to", to.String(),
	)
}

// Burn destroys a token. caller must be the token's current owner.
func Burn(cur realm, collectionID, tokenID string) {
	caller := unsafe.OriginCaller()
	c := mustGetCollection(collectionID)
	tid := grc721.TokenID(tokenID)

	owner, err := c.token.OwnerOf(tid)
	if err != nil {
		panic(err)
	}
	if owner != caller {
		panic("only the token owner can burn it")
	}
	if err := c.token.Burn(tid); err != nil {
		panic(err)
	}

	ownerIndex.Remove(owner.String() + ":" + collectionID + ":" + tokenID)

	chain.Emit("Burn", "collection", collectionID, "tokenId", tokenID, "from", owner.String())
}

// Read-only views.

// GetCollection returns the exported view of one collection.
func GetCollection(collectionID string) CollectionInfo {
	c := mustGetCollection(collectionID)
	return toInfo(c)
}

// ListCollections returns up to `limit` collections starting at `offset`,
// most-recently-created first is NOT guaranteed; ordering follows
// collection ID (creation order).
func ListCollections(offset, limit int64) []CollectionInfo {
	out := make([]CollectionInfo, 0, limit)
	collections.IterateByOffset(int(offset), int(limit), func(key string, value any) bool {
		out = append(out, toInfo(value.(*Collection)))
		return false
	})
	return out
}

// CollectionCount returns the total number of collections ever created.
func CollectionCount() int64 {
	return collCount
}

// TokensOfOwner returns "collectionId:tokenId" pairs for every token the
// given address owns, across every collection in this realm.
func TokensOfOwner(owner address) []string {
	var out []string
	prefix := owner.String() + ":"
	end := owner.String() + ";" // ';' immediately follows ':' in ASCII
	ownerIndex.Iterate(prefix, end, func(key string, value any) bool {
		out = append(out, key[len(prefix):])
		return false
	})
	return out
}

// BalanceOf returns how many tokens of one collection an address owns.
func BalanceOf(collectionID string, owner address) int64 {
	c := mustGetCollection(collectionID)
	bal, err := c.token.BalanceOf(owner)
	if err != nil {
		panic(err)
	}
	return bal
}

// OwnerOf returns the current owner of a token.
func OwnerOf(collectionID, tokenID string) (address, error) {
	c := mustGetCollection(collectionID)
	return c.token.OwnerOf(grc721.TokenID(tokenID))
}

// TokenURI returns the metadata URI of a token.
func TokenURI(collectionID, tokenID string) (string, error) {
	c := mustGetCollection(collectionID)
	return c.token.TokenURI(grc721.TokenID(tokenID))
}

// GetApproved returns the address approved for a single token, if any.
func GetApproved(collectionID, tokenID string) (address, error) {
	c := mustGetCollection(collectionID)
	return c.token.GetApproved(grc721.TokenID(tokenID))
}

// IsApprovedForAll reports whether operator can manage all of owner's
// tokens in one collection.
func IsApprovedForAll(collectionID string, owner, operator address) bool {
	c := mustGetCollection(collectionID)
	return c.token.IsApprovedForAll(owner, operator)
}

// RoyaltyInfo returns the payment address and royalty amount owed for a
// sale of the given token at salePrice (in the marketplace's denom units).
func RoyaltyInfo(collectionID, tokenID string, salePrice int64) (address, int64, error) {
	c := mustGetCollection(collectionID)
	return c.token.RoyaltyInfo(grc721.TokenID(tokenID), salePrice)
}

// Render implements the gno.land realm home-page convention so the
// factory is browsable directly from a gnoweb / explorer UI even without
// the dedicated frontend.
func Render(path string) string {
	if path != "" {
		id := path
		c := collections.Get(id)
		if c == nil {
			return "# 404\n\ncollection not found: " + id
		}
		return renderCollection(c.(*Collection))
	}

	out := ufmt.Sprintf("# Hazen NFT Factory\n\n%d collection(s)\n\n", collCount)
	collections.Iterate("", "", func(key string, value any) bool {
		c := value.(*Collection)
		out += ufmt.Sprintf(
			"- [#%s %s (%s)](/r/hazen/nft:%s) — %d/%d minted, by %s\n",
			c.id, c.name, c.symbol, c.id, c.token.TokenCount(), c.maxSupply, c.creator.String(),
		)
		return false
	})
	return out
}

func renderCollection(c *Collection) string {
	out := ufmt.Sprintf("# %s (%s)\n\n%s\n\n", c.name, c.symbol, c.description)
	out += ufmt.Sprintf("- Creator: %s\n", c.creator.String())
	out += ufmt.Sprintf("- Minted: %d / %d\n", c.token.TokenCount(), c.maxSupply)
	out += ufmt.Sprintf("- Public mint: %t\n", c.publicMint)
	out += ufmt.Sprintf("- Royalty: %d%%\n", c.royaltyPct)
	return out
}

func toInfo(c *Collection) CollectionInfo {
	return CollectionInfo{
		ID:          c.id,
		Name:        c.name,
		Symbol:      c.symbol,
		Description: c.description,
		BaseURI:     c.baseURI,
		Creator:     c.creator,
		MaxSupply:   c.maxSupply,
		Minted:      c.token.TokenCount(),
		PublicMint:  c.publicMint,
		RoyaltyPct:  c.royaltyPct,
		CreatedAt:   c.createdAt,
	}
}

func mustGetCollection(id string) *Collection {
	v := collections.Get(id)
	if v == nil {
		panic("collection not found: " + id)
	}
	return v.(*Collection)
}

package nft

import (
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

// NOTE: CreateCollection/Mint/Approve/SetApprovalForAll/Burn derive the
// caller from unsafe.OriginCaller(), which testing.SetOriginCaller(addr)
// correctly overrides for the remainder of the *calling function's own
// stack frame* — so every SetOriginCaller call below is inlined directly
// in the test/t.Run closure body, right before the action it's meant to
// affect. TransferFrom is the one exception that reads
// cur.Previous().Address() instead (see nft.gno), which in a same-package
// test always resolves to this realm's own address (cur.Address()) — so
// its test mints to cur.Address() as a stand-in "owner" rather than to a
// distinct testutils address.

func TestCreateCollectionAndMint(cur realm, t *testing.T) {
	alice := testutils.TestAddress("alice")
	bob := testutils.TestAddress("bob")

	var id, tid string

	t.Run("alice creates a collection", func(t *testing.T) {
		testing.SetOriginCaller(alice)
		id = CreateCollection(cross(cur), "Hazen Genesis", "HZNG", "test collection", "ipfs://base/", 10, 5, true)
		uassert.Equal(t, "1", id)

		info := GetCollection(id)
		uassert.Equal(t, "Hazen Genesis", info.Name)
		uassert.Equal(t, int64(10), info.MaxSupply)
		uassert.Equal(t, int64(0), info.Minted)
		uassert.Equal(t, alice, info.Creator)
	})

	t.Run("bob mints into it", func(t *testing.T) {
		testing.SetOriginCaller(bob)
		tid = Mint(cross(cur), id, "ipfs://base/1.json")
		uassert.Equal(t, "1", tid)

		owner, err := OwnerOf(id, tid)
		uassert.NoError(t, err, "OwnerOf should not error")
		uassert.Equal(t, bob, owner)

		uri, err := TokenURI(id, tid)
		uassert.NoError(t, err, "TokenURI should not error")
		uassert.Equal(t, "ipfs://base/1.json", uri)

		toks := TokensOfOwner(bob)
		uassert.Equal(t, 1, len(toks))
		uassert.Equal(t, id+":"+tid, toks[0])
	})

	t.Run("royalty was recorded for the creator", func(t *testing.T) {
		paymentAddr, amount, err := RoyaltyInfo(id, tid, 1000)
		uassert.NoError(t, err, "RoyaltyInfo should not error")
		uassert.Equal(t, alice, paymentAddr)
		uassert.Equal(t, int64(50), amount) // 5% of 1000
	})
}

func TestMintRestrictedToCreator(cur realm, t *testing.T) {
	alice := testutils.TestAddress("alice2")
	bob := testutils.TestAddress("bob2")

	var id string
	t.Run("alice creates a private-mint collection", func(t *testing.T) {
		testing.SetOriginCaller(alice)
		id = CreateCollection(cross(cur), "Private Drop", "PRIV", "", "", 3, 0, false)
	})

	t.Run("bob cannot mint into it", func(t *testing.T) {
		testing.SetOriginCaller(bob)
		uassert.AbortsWithMessage(t, cur, "minting into this collection is restricted to its creator", func() {
			Mint(cross(cur), id, "")
		})
	})

	t.Run("alice can mint into it", func(t *testing.T) {
		testing.SetOriginCaller(alice)
		tid := Mint(cross(cur), id, "")
		uassert.Equal(t, "1", tid)
	})
}

func TestMaxSupplyEnforced(cur realm, t *testing.T) {
	alice := testutils.TestAddress("alice3")

	var id string
	t.Run("create + mint the only token", func(t *testing.T) {
		testing.SetOriginCaller(alice)
		id = CreateCollection(cross(cur), "Tiny", "TINY", "", "", 1, 0, true)
		Mint(cross(cur), id, "")
	})

	t.Run("second mint is rejected", func(t *testing.T) {
		testing.SetOriginCaller(alice)
		uassert.AbortsWithMessage(t, cur, "collection has reached its max supply", func() {
			Mint(cross(cur), id, "")
		})
	})
}

func TestTransferFrom(cur realm, t *testing.T) {
	bob := testutils.TestAddress("bob4")

	var id, tid string
	self := cur.Address() // stand-in "owner" identity for this same-package test; see NOTE above

	t.Run("mint to self, then transfer to bob", func(t *testing.T) {
		testing.SetOriginCaller(self)
		id = CreateCollection(cross(cur), "Transferable", "TRF", "", "", 5, 0, true)
		tid = Mint(cross(cur), id, "")
		TransferFrom(cross(cur), id, tid, self, bob)
	})

	t.Run("bob is now the owner", func(t *testing.T) {
		owner, err := OwnerOf(id, tid)
		uassert.NoError(t, err, "OwnerOf should not error")
		uassert.Equal(t, bob, owner)
	})
}

// Package nftmarket is a non-custodial GNOT marketplace for collections
// minted through gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nft.
//
// Non-custodial: listing a token never moves it into this realm. Instead
// the seller approves this realm's address as an operator on
// gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nft (Approve or SetApprovalForAll), and List just
// records the intent to sell. At Buy time this realm cross-calls
// nft.TransferFrom on the seller's behalf — which only succeeds while the
// approval still stands — so a seller can invalidate every open listing
// at once just by transferring the token or revoking the approval.
package nftmarket

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nft"
)

// Listing is one active or historical sale offer.
type Listing struct {
	id           string
	collectionID string
	tokenID      string
	seller       address
	priceUgnot   int64
	active       bool
	createdAt    int64
}

// ListingInfo is the exported, read-only view of a Listing.
type ListingInfo struct {
	ID           string
	CollectionID string
	TokenID      string
	Seller       address
	PriceUgnot   int64
	Active       bool
	CreatedAt    int64
}

var (
	listings = avl.NewTree() // listingID -> *Listing
	byToken  = avl.NewTree() // "collectionId:tokenId" -> listingID (only one active listing per token)
	nextID   int64
)

// List offers a token for sale at priceUgnot (denominated in ugnot, i.e.
// 1 GNOT = 1_000_000). The caller must already own the token and must have
// approved this realm's address on gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nft beforehand
// (nft.Approve or nft.SetApprovalForAll), otherwise Buy will fail later.
func List(cur realm, collectionID, tokenID string, priceUgnot int64) string {
	// List/Cancel/Buy are always meant to be called directly by an EOA,
	// so caller comes from unsafe.OriginCaller() (the tx's real signer)
	// rather than cur.Previous().Address(). Only nft.TransferFrom (called
	// from Buy below) actually needs the direct-caller distinction, to
	// let this realm act as the seller's approved operator.
	caller := unsafe.OriginCaller()
	if priceUgnot <= 0 {
		panic("price must be positive")
	}

	owner, err := nft.OwnerOf(collectionID, tokenID)
	if err != nil {
		panic(err)
	}
	if owner != caller {
		panic("only the token owner can list it")
	}

	marketAddr := cur.Address()
	approved, _ := nft.GetApproved(collectionID, tokenID)
	if approved != marketAddr && !nft.IsApprovedForAll(collectionID, owner, marketAddr) {
		panic("marketplace is not approved to transfer this token yet; call nft.Approve or nft.SetApprovalForAll first")
	}

	key := collectionID + ":" + tokenID
	if listingID, ok := byToken.Get(key).(string); ok {
		if l, ok2 := listings.Get(listingID).(*Listing); ok2 && l.active {
			panic("token is already listed (listing #" + listingID + ")")
		}
	}

	nextID++
	id := strconv.FormatInt(nextID, 10)
	l := &Listing{
		id:           id,
		collectionID: collectionID,
		tokenID:      tokenID,
		seller:       caller,
		priceUgnot:   priceUgnot,
		active:       true,
		createdAt:    runtime.ChainHeight(),
	}
	listings.Set(id, l)
	byToken.Set(key, id)

	chain.Emit(
		"NFTListed",
		"listingId", id,
		"collection", collectionID,
		"tokenId", tokenID,
		"seller", caller.String(),
		"price", strconv.FormatInt(priceUgnot, 10),
	)

	return id
}

// Cancel withdraws an active listing. Only the original seller may cancel.
func Cancel(cur realm, listingID string) {
	caller := unsafe.OriginCaller()
	l := mustGetListing(listingID)
	if !l.active {
		panic("listing is not active")
	}
	if l.seller != caller {
		panic("only the seller can cancel this listing")
	}

	l.active = false
	byToken.Remove(l.collectionID + ":" + l.tokenID)

	chain.Emit("NFTListingCancelled", "listingId", listingID)
}

// Buy purchases an active listing. The transaction must send at least the
// listing's priceUgnot in ugnot (--send "<price>ugnot" on maketx call); any
// excess is refunded to the buyer. Royalties declared on the token (via
// its collection's royaltyPct, set automatically at Mint) are paid to the
// collection creator before the remainder goes to the seller.
func Buy(cur realm, listingID string) {
	caller := unsafe.OriginCaller()
	l := mustGetListing(listingID)
	if !l.active {
		panic("listing is not active")
	}
	if l.seller == caller {
		panic("cannot buy your own listing")
	}

	sent := unsafe.OriginSend()
	sentAmt := sent.AmountOf("ugnot")
	if sentAmt < l.priceUgnot {
		panic("insufficient payment: sent " + strconv.FormatInt(sentAmt, 10) +
			"ugnot, need " + strconv.FormatInt(l.priceUgnot, 10) + "ugnot")
	}

	marketAddr := cur.Address()
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)

	sellerAmt := l.priceUgnot
	if royaltyAddr, royaltyAmt, err := nft.RoyaltyInfo(l.collectionID, l.tokenID, l.priceUgnot); err == nil {
		if royaltyAmt > 0 && royaltyAmt < l.priceUgnot && royaltyAddr != l.seller {
			sellerAmt = l.priceUgnot - royaltyAmt
			bk.SendCoins(marketAddr, royaltyAddr, chain.NewCoins(chain.NewCoin("ugnot", royaltyAmt)))
		}
	}
	bk.SendCoins(marketAddr, l.seller, chain.NewCoins(chain.NewCoin("ugnot", sellerAmt)))

	if sentAmt > l.priceUgnot {
		bk.SendCoins(marketAddr, caller, chain.NewCoins(chain.NewCoin("ugnot", sentAmt-l.priceUgnot)))
	}

	// Cross into gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nft to move ownership. This only
	// succeeds if the seller's approval (granted directly on the nft
	// realm) is still standing; a revoked/expired approval reverts this
	// entire transaction, including the coin transfers above.
	nft.TransferFrom(cross(cur), l.collectionID, l.tokenID, l.seller, caller)

	l.active = false
	byToken.Remove(l.collectionID + ":" + l.tokenID)

	chain.Emit(
		"NFTSold",
		"listingId", listingID,
		"collection", l.collectionID,
		"tokenId", l.tokenID,
		"seller", l.seller.String(),
		"buyer", caller.String(),
		"price", strconv.FormatInt(l.priceUgnot, 10),
	)
}

// Read-only views.

// GetListing returns one listing by ID.
func GetListing(listingID string) ListingInfo {
	return toInfo(mustGetListing(listingID))
}

// ListActive returns up to `limit` active listings starting at `offset`
// (offset/limit apply to the full listing set, active or not, so callers
// should over-fetch slightly if they need an exact page of active-only
// results).
func ListActive(offset, limit int64) []ListingInfo {
	out := make([]ListingInfo, 0, limit)
	listings.IterateByOffset(int(offset), int(limit), func(key string, value any) bool {
		l := value.(*Listing)
		if l.active {
			out = append(out, toInfo(l))
		}
		return false
	})
	return out
}

// ListingCount returns the total number of listings ever created
// (active + inactive).
func ListingCount() int64 {
	return nextID
}

// Render implements the gno.land realm home-page convention.
func Render(path string) string {
	if path != "" {
		l, ok := listings.Get(path).(*Listing)
		if !ok {
			return "# 404\n\nlisting not found: " + path
		}
		return renderListing(l)
	}

	out := "# Hazen NFT Marketplace\n\n"
	hasActive := false
	listings.Iterate("", "", func(key string, value any) bool {
		l := value.(*Listing)
		if !l.active {
			return false
		}
		hasActive = true
		out += renderListing(l) + "\n"
		return false
	})
	if !hasActive {
		out += "No active listings.\n"
	}
	return out
}

func renderListing(l *Listing) string {
	status := "active"
	if !l.active {
		status = "sold/cancelled"
	}
	return "- #" + l.id + " " + l.collectionID + ":" + l.tokenID +
		" — " + strconv.FormatInt(l.priceUgnot, 10) + "ugnot — seller " + l.seller.String() +
		" (" + status + ")"
}

func toInfo(l *Listing) ListingInfo {
	return ListingInfo{
		ID:           l.id,
		CollectionID: l.collectionID,
		TokenID:      l.tokenID,
		Seller:       l.seller,
		PriceUgnot:   l.priceUgnot,
		Active:       l.active,
		CreatedAt:    l.createdAt,
	}
}

func mustGetListing(id string) *Listing {
	v := listings.Get(id)
	if v == nil {
		panic("listing not found: " + id)
	}
	return v.(*Listing)
}

package nftmarket

import (
	"chain"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nft"
)

// NOTE: testing.SetOriginCaller overrides unsafe.OriginCaller() for the
// remainder of the *calling function's own stack frame* — so every call
// below is inlined directly in the test/t.Run closure body, right before
// the action(s) it's meant to affect (see nft_test.gno for more detail on
// why factoring this into a shared helper function breaks it).

func TestListAndBuy(cur realm, t *testing.T) {
	alice := testutils.TestAddress("mkt-alice")
	bob := testutils.TestAddress("mkt-bob")

	var collID, tid, listingID string
	marketAddr := cur.Address()

	t.Run("alice creates, mints, approves and lists", func(t *testing.T) {
		testing.SetOriginCaller(alice)
		collID = nft.CreateCollection(cross(cur), "Market Test", "MKT", "", "", 5, 10, true)
		tid = nft.Mint(cross(cur), collID, "")
		nft.Approve(cross(cur), collID, tid, marketAddr)
		listingID = List(cross(cur), collID, tid, 1_000_000) // 1 GNOT

		info := GetListing(listingID)
		uassert.True(t, info.Active, "listing should be active")
		uassert.Equal(t, int64(1_000_000), info.PriceUgnot)
	})

	t.Run("bob buys it", func(t *testing.T) {
		testing.SetOriginCaller(bob)
		// On real chain, a --send amount is credited to the CALLED
		// REALM's account before the function runs; gno test doesn't do
		// this automatically, so IssueCoins simulates that deposit onto
		// the marketplace realm itself (not bob) to match what Buy's
		// banker.SendCoins calls actually need.
		testing.IssueCoins(marketAddr, chain.NewCoins(chain.NewCoin("ugnot", 1_000_000)))
		testing.SetOriginSend(chain.NewCoins(chain.NewCoin("ugnot", 1_000_000)))

		Buy(cross(cur), listingID)

		owner, err := nft.OwnerOf(collID, tid)
		uassert.NoError(t, err, "OwnerOf should not error")
		uassert.Equal(t, bob, owner)

		sold := GetListing(listingID)
		uassert.False(t, sold.Active, "listing should be inactive after sale")
	})
}

func TestCancelListing(cur realm, t *testing.T) {
	alice := testutils.TestAddress("mkt-alice2")
	marketAddr := cur.Address()

	var listingID string
	t.Run("alice lists then cancels", func(t *testing.T) {
		testing.SetOriginCaller(alice)
		collID := nft.CreateCollection(cross(cur), "Cancel Test", "CNCL", "", "", 5, 0, true)
		tid := nft.Mint(cross(cur), collID, "")
		nft.Approve(cross(cur), collID, tid, marketAddr)

		listingID = List(cross(cur), collID, tid, 500_000)
		Cancel(cross(cur), listingID)
	})

	t.Run("listing is inactive", func(t *testing.T) {
		info := GetListing(listingID)
		uassert.False(t, info.Active, "listing should be inactive after cancel")
	})
}

func TestListRequiresApproval(cur realm, t *testing.T) {
	alice := testutils.TestAddress("mkt-alice3")

	t.Run("listing without approval aborts", func(t *testing.T) {
		testing.SetOriginCaller(alice)
		collID := nft.CreateCollection(cross(cur), "NoApprove", "NOAP", "", "", 5, 0, true)
		tid := nft.Mint(cross(cur), collID, "")

		uassert.AbortsWithMessage(t, cur,
			"marketplace is not approved to transfer this token yet; call nft.Approve or nft.SetApprovalForAll first",
			func() {
				List(cross(cur), collID, tid, 1)
			},
		)
	})
}

func TestCannotBuyOwnListing(cur realm, t *testing.T) {
	alice := testutils.TestAddress("mkt-alice4")
	marketAddr := cur.Address()

	var listingID string
	t.Run("alice lists", func(t *testing.T) {
		testing.SetOriginCaller(alice)
		collID := nft.CreateCollection(cross(cur), "SelfBuy", "SELF", "", "", 5, 0, true)
		tid := nft.Mint(cross(cur), collID, "")
		nft.Approve(cross(cur), collID, tid, marketAddr)
		listingID = List(cross(cur), collID, tid, 100)
	})

	t.Run("alice cannot buy it back", func(t *testing.T) {
		testing.SetOriginCaller(alice)
		testing.IssueCoins(alice, chain.NewCoins(chain.NewCoin("ugnot", 1_000)))
		testing.SetOriginSend(chain.NewCoins(chain.NewCoin("ugnot", 100)))

		uassert.AbortsWithMessage(t, cur, "cannot buy your own listing", func() {
			Buy(cross(cur), listingID)
		})
	})
}
